// Rebuild the service worker's precache list.
//
//   node tools/build-precache.mjs      (or: npm run precache)
//
// Walks everything the game actually needs to start, writes it into
// sw-precache.js with a content hash as the cache version, and stops there.
// It is not a build step: the game still runs from source, unbundled, exactly
// as it did before. This only tells the service worker what to keep.
//
// The generated file is COMMITTED, and tests/pwa.test.js re-walks the tree and
// fails if it has drifted. This project has forgotten to update a hard-coded
// list four separate times (see docs/lessons.md); a red test is a much better
// way to find out than a deploy that serves half an app.

import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative, dirname, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

/** Files at the root that the app cannot start without. */
const ROOT_FILES = ['index.html', 'styles.css', 'manifest.webmanifest'];

/** Directories walked whole, with the extensions worth keeping from each. */
const TREES = [
  { dir: 'src', extensions: ['.js'] },
  { dir: 'icons', extensions: ['.png'] },
];

function walk(dir, extensions, found = []) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      walk(full, extensions, found);
    } else if (extensions.some((ext) => entry.endsWith(ext))) {
      found.push(full);
    }
  }
  return found;
}

/**
 * Every asset, as a relative URL.
 *
 * Relative, always — the app is served from a subpath on GitHub Pages
 * (/kingdom-sim/), and a leading slash would send the service worker looking
 * for these at the domain root.
 */
export function collectAssets() {
  const files = [];

  for (const name of ROOT_FILES) {
    try {
      statSync(join(ROOT, name));
      files.push(name);
    } catch {
      /* not built yet: the manifest arrives with the rest of M6 */
    }
  }

  for (const { dir, extensions } of TREES) {
    let absolute;
    try {
      absolute = statSync(join(ROOT, dir)).isDirectory() ? join(ROOT, dir) : null;
    } catch {
      continue;
    }
    if (!absolute) continue;
    for (const file of walk(absolute, extensions)) {
      files.push(relative(ROOT, file).split(sep).join('/'));
    }
  }

  files.sort();
  // './' is the start URL itself, which is what a navigation actually requests.
  return ['./', ...files.map((f) => `./${f}`)];
}

/** A version that changes when, and only when, the shipped bytes change. */
export function hashOf(assets) {
  const hash = createHash('sha256');
  for (const asset of assets) {
    hash.update(asset);
    if (asset === './') continue;
    hash.update(readFileSync(join(ROOT, asset.slice(2))));
  }
  return hash.digest('hex').slice(0, 12);
}

export function render(assets, version) {
  const list = assets.map((a) => `  '${a}',`).join('\n');
  return `// GENERATED by tools/build-precache.mjs -- do not edit by hand.\n`
    + `// Run \`npm run precache\` after changing anything the app loads.\n`
    + `// tests/pwa.test.js fails if this has drifted from what is on disk.\n`
    + `\n`
    + `const VERSION = 'ks-${version}';\n`
    + `const ASSETS = [\n${list}\n];\n`;
}

if (process.argv[1] && process.argv[1].endsWith('build-precache.mjs')) {
  const assets = collectAssets();
  const version = hashOf(assets);
  writeFileSync(join(ROOT, 'sw-precache.js'), render(assets, version).replace(/\n/g, '\r\n'));
  console.log(`sw-precache.js: ${assets.length} assets, version ks-${version}`);
}
